if(!session)return <div className="admin-login"><div className="login-brand">EASY <b>SHOP</b></div><form onSubmit={login}><span className="eyebrow">ADMIN PORTAL</span><h1>Welcome back</h1><p>Sign in to manage your store.</p><input type="email" required placeholder="Admin email" value={email} onChange={e=>setEmail(e.target.value)}/><input type="password" required placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)}/>{loginError&&<div className="error">{loginError}</div>}<button className="primary full">Sign in</button></form></div>;
if(role===null)return <div className="admin-loading">Checking admin access…</div>;
